from pathlib import Path
import base64, gzip

ROOT = Path('buildsrc/quiet-diary')

def write_gz64(rel: str, payload: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

FILES = {
'app/src/main/res/layout/activity_self_suggestion.xml': '',
'app/src/main/res/layout/activity_wake_settings.xml': '',
'app/src/main/res/layout/activity_wake_alarm.xml': '',
}

for rel, payload in FILES.items():
    write_gz64(rel, payload)

gradle = ROOT / 'app/build.gradle.kts'
text = gradle.read_text(encoding='utf-8')
old = '        versionCode = 30021\n        versionName = "0.30.2.1"\n'
new = '        versionCode = 30030\n        versionName = "0.30.3"\n'
if old not in text:
    raise SystemExit('0.30.2.1 version block not found')
gradle.write_text(text.replace(old, new, 1), encoding='utf-8')
print('Somnori 0.30.3 Premium Pass B applied')
